   if(Math.hypot(pts[0].x-pts[pts.length-1].x,pts[0].y-pts[pts.length-1].y)<1e-4)pts.pop();
   // Analytic outward normals: direction from the inner (core) rectangle.
   const ix=hw-r,iy=hh-r;
