   const nO=ring.length,pos=[],nor=[],idx=[];
   for(const [o,z,nr,nz] of prof)for(const [x,y,nx,ny] of ring){pos.push(x+nx*o,y+ny*o,z);nor.push(nx*nr,ny*nr,nz)}
