  const lin=h=>{const c=new THREE.Color(h);return new THREE.Vector3(c.r,c.g,c.b)};
  const tint=h=>{const v=lin(h),l=.2126*v.x+.7152*v.y+.0722*v.z;return v.multiplyScalar(1/l)};
  // Silver holo: pastel tints that multiply the silver reflection.
