   gl.enable(gl.BLEND);gl.blendFunc(gl.ONE,gl.ONE);gl.disable(gl.CULL_FACE);
   gl.useProgram(cprog);
   gl.uniform1i(cl('uSim'),0);gl.uniform1i(cl('uText'),1);
   gl.uniform2f(cl('uGrid'),GW,GH);gl.uniform2f(cl('uDom'),DOM[0],DOM[1]);
