 streak*=smoothstep(-178.,-112.,hx)*(1.-smoothstep(80.,94.,hx))+.7*smoothstep(102.,112.,hx)*(1.-smoothstep(142.,160.,hx));
 inside=mix(inside,vec3(1.),streak*mix(.78,.17,dk));
 inside+=vec3(1.)*exp(-max(hd,0.)/9.)*smoothstep(-20.,8.,hp.y)*(1.-smoothstep(80.,190.,abs(hp.x)))*mix(.05,.035,dk);
