 inside+=bulbC*exp(-pow((sIn-4.)/1.8,2.))*smoothstep(.3,1.,-n.y)*mix(.22,.35,dk)*(.7+.5*heat+.9*uRelax);
 // Wax close to the glass lights up the wall next to it.
