  const cam=api.perspective(26),CZ=cam.position.z;
  const scene=new T.Scene();
  const btn=api.board.querySelector('.gd-btn'),face=btn.querySelector('.gd-face'),label=btn.querySelector('.gd-label');

  // ── Studio ────────────────────────────────────────────────────────────────
  // Softboxes in direction space: [azimuth°, elevation°, half-az°, half-el°,
  // edge°, intensity, r,g,b]. Azimuth 0 is toward the viewer (+z), +90 is +x.
